/** Bounded current-versus-proposed terrain checks, including retained installed native models. */
import{readFileSync,writeFileSync}from'node:fs';import{createHash}from'node:crypto';import{makeTerrainSampler,inPolygon}from'../../../3d-viewer/city/geo.js';
const read=p=>JSON.parse(readFileSync(p)),mf=read('3d-viewer/city/data/manifest.json'),base=read('3d-viewer/city/data/terrain.json'),bundle=read('docs/astra-city/residual-support-review/capitol/terrain-bundle.json'),patches=bundle.bundles.flatMap(b=>b.patches.map(p=>({...p,data:read(p.path)}))),remove=new Set(patches.flatMap(p=>p.replacesExistingManifestPatches||p.data.meta.replacesExistingManifestPatches||[]));base.patches=mf.terrainPatches.map(p=>read('3d-viewer/'+p.url));const before=makeTerrainSampler(base),after=makeTerrainSampler({...base,patches:[...mf.terrainPatches.filter(p=>!remove.has(p.url)).map(p=>read('3d-viewer/'+p.url)),...patches.map(p=>p.data)]});
