for(const t of mf.tiles){if(!bbs.some(b=>intersects(t.bounds,b)))continue;for(const b of read('3d-viewer/'+t.url).buildings){const ring=b.rings[0],bb=[Math.min(...ring.map(p=>p[0])),Math.min(...ring.map(p=>p[1])),Math.max(...ring.map(p=>p[0])),Math.max(...ring.map(p=>p[1]))];if(!bbs.some(p=>intersects(bb,p)))continue;const pts=[];for(const r of b.rings)for(let i=1;i<r.length;i++)pts.push(r[i],[(r[i][0]+r[i-1][0])/2,(r[i][1]+r[i-1][1])/2]);const centre=[(bb[0]+bb[2])/2,(bb[1]+bb[3])/2];if(inPolygon(...centre,b.rings))pts.push(centre);const a=pts.map(p=>before.height(...p)),z=pts.map(p=>after.height(...p)),flags=v=>({roofBelow:v.some(h=>b.base+b.height<h-.25),baseAbove:v.every(h=>b.base>h+.5)}),f=flags(a),g=flags(z);rows.push({uid:b.uid,name:b.name,base:b.base,roof:b.base+b.height,baseSource:b.baseSource,heightSource:b.heightSource,before:[Math.min(...a),Math.max(...a)],after:[Math.min(...z),Math.max(...z)],samples:pts.length,newFlags:Object.keys(g).filter(k=>g[k]&&!f[k])});}}
const boundary=patches.map(p=>{const d=p.data,b=bounds(d),points=[];for(let x=b[0];x<=b[2];x+=1)points.push([x,b[1]],[x,b[3]]);for(let z=b[1];z<=b[3];z+=1)points.push([b[0],z],[b[2],z]);return{path:p.path,sha256:createHash('sha256').update(readFileSync(p.path)).digest('hex'),points:points.length,maxChange:Math.max(...points.map(q=>Math.abs(before.height(...q)-after.height(...q))))};});
const result={issue:'HKS-214',samples:'All affected source ring vertices and midpoints plus interior box centres; finite footprint sampling, not exhaustive triangle-intersection extrema.',buildings:rows.length,boundary,regressions:rows.filter(r=>r.newFlags.length),rows,publicationApproved:false};writeFileSync('docs/astra-city/residual-support-review/capitol/neighbours.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({...result,rows:undefined},null,2));
